function validate(input) {
  const [{ activity = [] }] = input;
  const seen = new Set(), days = new Map();
  for (const [user, date, action] of activity) {
    if (user === null || date === null || action === null) return 'No column may be null.';
    // A real calendar date survives a round trip through Date unchanged.
    const day = /^\d{4}-\d{2}-\d{2}$/.test(date) ? new Date(`${date}T00:00:00Z`) : null;
    if (!day || Number.isNaN(day.getTime()) || day.toISOString().slice(0, 10) !== date) return `action_date ${date} must be a real date like 2024-01-31.`;
    if (!/^[a-z_]+$/.test(action)) return `action ${action} must be a lowercase word.`;
    if (seen.has(`${user}|${date}|${action}`)) return `User ${user} logs ${action} twice on ${date}.`;
    seen.add(`${user}|${date}|${action}`);
    if (!days.has(user)) days.set(user, new Map());
    const byDate = days.get(user);
    byDate.set(date, [...(byDate.get(date) ?? []), action]);
  }
  // Every user's longest streak of at least 5 days must be unique.
  const next = d => new Date(Date.parse(`${d}T00:00:00Z`) + 86400000).toISOString().slice(0, 10);
  for (const [user, byDate] of days) {
    const single = [...byDate].filter(([, actions]) => actions.length === 1).map(([d, [a]]) => [d, a]).sort((x, y) => (x[0] < y[0] ? -1 : 1));
    const lengths = [];
    for (let i = 0; i < single.length; i++) {
      if (i > 0 && single[i - 1][1] === single[i][1] && next(single[i - 1][0]) === single[i][0]) lengths[lengths.length - 1]++;
      else lengths.push(1);
    }
    const best = Math.max(0, ...lengths);
    if (best >= 5 && lengths.filter(n => n === best).length > 1) return `User ${user} has two longest streaks of ${best} days.`;
  }
  return null;
}

