function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  const actions = small ? ['login', 'view', 'click'] : ['login', 'view', 'click', 'logout', 'search', 'share'];
  const day = offset => new Date(Date.UTC(2024, 1, 20) + offset * 86400000).toISOString().slice(0, 10);
  const rows = [];
  let budget = small ? pick(9) : 2000;
  for (let user = 1; budget > 0; user++) {
    let offset = small ? pick(5) : pick(40), current = actions[pick(actions.length)];
    const span = small ? budget : Math.min(budget, 5 + pick(40));
    let used = 0;
    while (used < span) {
      const roll = rand();
      if (roll < 0.08) { offset++; continue; } // a missing day
      if (rand() < (small ? 0.15 : 0.2)) current = actions[pick(actions.length)];
      rows.push([user, day(offset), current]);
      used++;
      // Sometimes a second, different action lands on the same day and breaks the streak.
      if (roll > 0.92 && used < span) {
        rows.push([user, day(offset), actions[(actions.indexOf(current) + 1) % actions.length]]);
        used++;
      }
      offset++;
    }
    budget -= used;
  }
  // Shorten one of any two tied longest streaks (5+ days) by dropping its last day, until each user's longest is unique.
  const next = d => new Date(Date.parse(`${d}T00:00:00Z`) + 86400000).toISOString().slice(0, 10);
  for (let changed = true; changed;) {
    changed = false;
    const byUser = new Map();
    for (const row of rows) {
      if (!byUser.has(row[0])) byUser.set(row[0], new Map());
      const byDate = byUser.get(row[0]);
      byDate.set(row[1], [...(byDate.get(row[1]) ?? []), row]);
    }
    for (const byDate of byUser.values()) {
      const single = [...byDate.values()].filter(list => list.length === 1).map(list => list[0]).sort((x, y) => (x[1] < y[1] ? -1 : 1));
      const runs = [];
      for (let i = 0; i < single.length; i++) {
        if (i > 0 && single[i - 1][2] === single[i][2] && next(single[i - 1][1]) === single[i][1]) runs[runs.length - 1].push(single[i]);
        else runs.push([single[i]]);
      }
      const best = Math.max(0, ...runs.map(r => r.length));
      const tied = runs.filter(r => r.length === best);
      if (best >= 5 && tied.length > 1) {
        rows.splice(rows.indexOf(tied[1][best - 1]), 1);
        changed = true;
      }
    }
  }
  // Store rows in a shuffled order so the table is not already sorted by date.
  for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ activity: rows }];
}
